from pathlib import Path
import base64,subprocess,json
r=Path('/mnt/BioDisk/wangmingyuan/osteosarcoma_CAF/phase51_matrix_lineage_attribution_20261002')
assert (r/'analysis.exit_code').read_text().strip()=='0'
(r/'code/independent_QA.R').write_bytes(base64.b64decode(''))
(r/'code/parse_QA.R').write_text('parse(file="'+str(r/'code/independent_QA.R')+'")')
x=subprocess.run(['/mnt/BioDisk/wangmingyuan/miniconda3/envs/R_4.5.2/bin/Rscript','--vanilla',str(r/'code/parse_QA.R')],capture_output=True,text=True)
(r/'logs/R_parse.log').write_text(x.stdout+x.stderr);assert x.returncode==0,x.stderr
with (r/'logs/independent_R.log').open('w') as log:
 proc=subprocess.Popen(['/usr/bin/time','-v','/mnt/BioDisk/wangmingyuan/miniconda3/envs/R_4.5.2/bin/Rscript','--vanilla',str(r/'code/independent_QA.R')],stdout=log,stderr=subprocess.STDOUT,cwd=r);(r/'independent_R.pid').write_text(str(proc.pid));rc=proc.wait()
(r/'independent_R.exit_code').write_text(str(rc))
